add_filter( 'woocommerce_email_subject_customer_processing_order', 'perfectpixel_processing_subject', 20, 2 );
add_filter( 'woocommerce_email_subject_customer_completed_order', 'perfectpixel_completed_subject', 20, 2 );

function perfectpixel_personal_subject( $template, $subject, $order ) {
	if ( '' === trim( $template ) || ! $order instanceof WC_Order ) {
		return $subject;
	}
	$name = $order->get_billing_first_name();
	$text = str_replace(
		array( '{first_name}', '{order_number}', '{site_title}' ),
		array( $name, $order->get_order_number(), wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
		$template
	);
	return '' === $name ? ltrim( $text, ', ' ) : $text;
}

function perfectpixel_processing_subject( $subject, $order ) {
	return perfectpixel_personal_subject( '{{processing_subject}}', $subject, $order );
}

function perfectpixel_completed_subject( $subject, $order ) {
	return perfectpixel_personal_subject( '{{completed_subject}}', $subject, $order );
}
